from shiny import App, ui, render

app_ui = ui.page_sidebar(
    ui.sidebar(
        ui.input_text("n", "Your name", "world"),
    ),
    ui.output_text("greeting"),
)

def server(input, output, session):
    @output
    @render.text
    def greeting():
        return f"Hello, {input.n()}!"

app = App(app_ui, server)

