from shiny import App, ui, render, reactive

app_ui = ui.page_sidebar(
    ui.sidebar(ui.input_numeric("x", "X", 1)),
    ui.output_text("out"),
    ui.output_text("out2"),
)

def server(input, output, session):
    # add reactive y = x * 2
    @output
    @render.text
    def out():
        return f"y = {input.x() * 2}"

    @output
    @render.text
    def out2():
        return f"y again = {input.x() * 2}"

app = App(app_ui, server)

