from shiny import App, ui, render, reactive

app_ui = ui.page_sidebar(
    ui.sidebar(
        ui.input_slider("x", "X", 0, 10, 1),
        ui.input_action_button("go", "Commit"),
    ),
    ui.output_text("out"),
)

def server(input, output, session):
    # out should only update when go is pressed
    @output
    @render.text
    def out():
        return f"x = {input.x()}"

app = App(app_ui, server)

